import{_ as l,a0 as r,w as o,s as d,ao as p,I as i,a1 as t,A as a,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"將你的安卓手機屏幕投射到 Linux | LCTT x X-CMD","titleTemplate":false,"description":"將你的安卓手機屏幕投射到 Linux | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"將你的安卓手機屏幕投射到 Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"將你的安卓手機屏幕投射到 Linux | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210308 Cast your Android device with a Raspberry Pi","title":"將你的安卓手機屏幕投射到 Linux","tag":"202104","desc":""},"relativePath":"202104/20210308 Cast your Android device with a Raspberry Pi.md","filePath":"[post].md"}'),u={name:"202104/20210308 Cast your Android device with a Raspberry Pi.md"};function b(g,s,y,m,h,f){const e=r("Link");return o(),d("div",null,[s[36]||(s[36]=p('<h1 id="將你的安卓手機屏幕投射到-linux" tabindex="-1">將你的安卓手機屏幕投射到 Linux <a class="header-anchor" href="#將你的安卓手機屏幕投射到-linux" aria-label="Permalink to “將你的安卓手機屏幕投射到 Linux”">​</a></h1><blockquote><p>使用 Scrcpy 可以把你的手機屏幕變成一個“應用”，與在樹莓派或任何其他基於 Linux 的設備上的應用一起運行。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202104/20/162346alpbh85xz26xcb5h.jpg" alt=""></p><p>要遠離我們日常使用的電子產品是很難的。在熙熙攘攘的現代生活中，我想確保我不會錯過手機屏幕上彈出的來自朋友和家人的重要信息。我也很忙，不希望迷失在令人分心的事情中，但是拿起手機並且回覆信息往往會使我分心。</p><p>更糟糕的是，有很多的設備。幸運地是，大多數的設備（從功能強大的筆記本電腦到甚至不起眼的樹莓派）都可以運行 Linux。因為它們運行的是 Linux，所以我為一種設置找到的解決方案几乎都適用於其他設備。</p><h3 id="普遍適用" tabindex="-1">普遍適用 <a class="header-anchor" href="#普遍適用" aria-label="Permalink to “普遍適用”">​</a></h3><p>我想要一種無論我使用什麼屏幕，都能統一我生活中不同來源的數據的方法。</p><p>我決定通過把手機屏幕複製到電腦上來解決這個問題。本質上，我把手機變成了一個“應用”，可以和我所有的其他程序運行在一起。這有助於我將注意力集中在桌面上，防止我走神，並使我更容易回覆緊急通知。</p><p>聽起來有吸引力嗎？你也可以這樣做。</p><h3 id="設置-scrcpy" tabindex="-1">設置 Scrcpy <a class="header-anchor" href="#設置-scrcpy" aria-label="Permalink to “設置 Scrcpy”">​</a></h3>',10)),i("p",null,[t(e,{href:"https://github.com/Genymobile/scrcpy"},{default:a(()=>[...s[0]||(s[0]=[n("Scrcpy",-1)])]),_:1}),s[1]||(s[1]=n(" 俗稱屏幕複製（Screen Copy），是一個開源的屏幕鏡像工具，它可以在 Linux、Windows 或者 macOS 上顯示和控制安卓設備。安卓設備和計算機之間的通信主要是通過 USB 連接和",-1)),s[2]||(s[2]=i("ruby",null,[n("安卓調試橋"),i("rt",null,"Android Debug Bridge")],-1)),s[3]||(s[3]=n("（ADB）。它使用 TCP/IP，且不需要 root 權限訪問。",-1))]),s[37]||(s[37]=p(`<p>Scrcpy 的設置和配置非常簡單。如果你正在運行 Fedora，你可以從 COPR 倉庫安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf copr enable zeno/scrcpy</span></span>
<span class="line"><span>$ sudo dnf install scrcpy -y</span></span></code></pre></div><p>在 Debian 或者 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install scrcpy</span></span></code></pre></div>`,4)),i("p",null,[s[5]||(s[5]=n("你也可以自己編譯 Scrcpy。即使是在樹莓派上，按照 ",-1)),t(e,{href:"https://github.com/Genymobile/scrcpy/blob/master/BUILD.md"},{default:a(()=>[...s[4]||(s[4]=[n("Scrcpy 的 GitHub 主頁",-1)])]),_:1}),s[6]||(s[6]=n(" 上的説明來構建也不需要很長時間。",-1))]),s[38]||(s[38]=i("h3",{id:"設置手機",tabindex:"-1"},[n("設置手機 "),i("a",{class:"header-anchor",href:"#設置手機","aria-label":"Permalink to “設置手機”"},"​")],-1)),s[39]||(s[39]=i("p",null,"Scrcpy 安裝好後，你必須啓用 USB 調試並授權每個設備（你的樹莓派、筆記本電腦或者工作站）為受信任的控制器。",-1)),i("p",null,[s[8]||(s[8]=n("打開安卓上的“設置”應用程序。如果“開發者選項”沒有被激活，按照安卓的 ",-1)),t(e,{href:"https://developer.android.com/studio/debug/dev-options"},{default:a(()=>[...s[7]||(s[7]=[n("説明來解鎖它",-1)])]),_:1}),s[9]||(s[9]=n("。",-1))]),s[40]||(s[40]=i("p",null,"接下來，啓用“USB 調試”。",-1)),s[41]||(s[41]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/uploads/usb-debugging.jpg",alt:"Enable USB Debugging option",title:"Enable USB Debugging option"})],-1)),i("p",null,[s[11]||(s[11]=n("然後通過 USB 將手機連接到你的樹莓派或者筆記本電腦（或者你正在使用的任何設備），如果可以選擇的話，將模式設置為 ",-1)),t(e,{href:"https://en.wikipedia.org/wiki/Picture_Transfer_Protocol"},{default:a(()=>[...s[10]||(s[10]=[n("PTP",-1)])]),_:1}),s[12]||(s[12]=n("。如果你的手機不能使用 PTP，將你的手機設置為用於傳輸文件的模式（而不是，作為一個",-1)),s[13]||(s[13]=i("ruby",null,[n("疊接"),i("rt",null,"tethering")],-1)),s[14]||(s[14]=n("或者 MIDI 設備）。",-1))]),s[42]||(s[42]=p(`<p>你的手機可能會提示你授權你的電腦，這是通過它的 RSA 指紋進行識別的。你只需要在你第一次連接的時候操作即可，在之後你的手機會識別並信任你的計算機。</p><p>使用 <code>lsusb</code> 命令確認設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb</span></span>
<span class="line"><span>Bus 007 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span>
<span class="line"><span>Bus 011 Device 004: ID 046d:c21d Logitech, Inc. F310 Gamepad</span></span>
<span class="line"><span>Bus 005 Device 005: ID 0951:1666 Kingston Technology DataTraveler G4</span></span>
<span class="line"><span>Bus 005 Device 004: ID 05e3:0608 Genesys Logic, Inc. Hub</span></span>
<span class="line"><span>Bus 004 Device 001: ID 18d1:4ee6 Google Inc. Nexus/Pixel Device (PTP + debug)</span></span>
<span class="line"><span>Bus 003 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span>
<span class="line"><span>Bus 002 Device 001: ID 1d6b:0003 Linux Foundation 3.0 root hub</span></span>
<span class="line"><span>Bus 001 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span></code></pre></div><p>然後執行 <code>scrcpy</code> 以默認設置運行。</p><p><img src="https://opensource.com/sites/default/files/uploads/scrcpy-pi.jpg" alt="Scrcpy running on a Raspberry Pi" title="Scrcpy running on a Raspberry Pi"></p><p>性能和響應能力取決於你使用什麼設備來控制你的手機。在樹莓派派上，一些動畫可能會變慢，甚至有時候會響應滯後。Scrcpy 提供了一個簡單的解決辦法：降低 Scrcpy 顯示圖像的位速率和分辨率使得你的計算機能夠容易顯示動畫。使用以下命令來實現：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scrcpy --bit-rate 1M --max-size 800</span></span></code></pre></div>`,7)),i("p",null,[s[16]||(s[16]=n("嘗試不同的值來找到一個適合你的值。為了使鍵入更方便，在選定一個命令之後，可以考慮 ",-1)),t(e,{href:"https://opensource.com/article/19/7/bash-aliases"},{default:a(()=>[...s[15]||(s[15]=[n("創建自己的 Bash 別名",-1)])]),_:1}),s[17]||(s[17]=n("。",-1))]),s[43]||(s[43]=p(`<h3 id="剪斷連線" tabindex="-1">剪斷連線 <a class="header-anchor" href="#剪斷連線" aria-label="Permalink to “剪斷連線”">​</a></h3><p>Scrcpy 開始運行後，你甚至可以通過 WiFi 連接你的手機和計算機。Scrcpy 安裝過程也會安裝 <code>adb</code>，它是一個與安卓設備通信的命令。Scrcpy 也可以使用這個命令與你的設備通信，<code>adb</code> 可以通過 TCP/IP 連接。</p><p><img src="https://opensource.com/sites/default/files/uploads/ssur-desktop.png" alt="Scrcpy running on a computer" title="Scrcpy running on a computer"></p><p>要嘗試的話，請確保你的手機通過 WiFi 連在與你的計算機所使用的相同的無線網絡上。依然不要斷開你的手機與 USB 的連接！</p><p>接下來，通過手機中的“設置”，選擇“關於手機”來獲取你手機的 IP 地址。查看“狀態”選項來獲得你的地址。它通常是 192.168 或者 10 開頭。</p><p>或者，你也可以使用 <code>adb</code> 來獲得你手機的IP地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ adb shell ip route | awk &#39;{print $9}&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To connect to your device over WiFi, you must enable TCP/IP connections. This, you must do through the adb command:</span></span>
<span class="line"><span>$ adb tcpip 5555</span></span>
<span class="line"><span>Now you can disconnect your mobile from USB.</span></span>
<span class="line"><span>Whenever you want to connect over WiFi, first connect to the mobile with the command adb connect. For instance, assuming my mobile&#39;s IP address is 10.1.1.22, the command is:</span></span>
<span class="line"><span>$ adb connect 10.1.1.22:5555</span></span></code></pre></div><p>連接好之後，你就可以像往常一樣運行 Scrcpy 了。</p><h3 id="遠程控制" tabindex="-1">遠程控制 <a class="header-anchor" href="#遠程控制" aria-label="Permalink to “遠程控制”">​</a></h3>`,9)),i("p",null,[s[19]||(s[19]=n("Scrcpy 很容易使用。你可以在終端或者 ",-1)),t(e,{href:"https://opensource.com/article/19/9/mirror-android-screen-guiscrcpy"},{default:a(()=>[...s[18]||(s[18]=[n("一個圖形界面應用",-1)])]),_:1}),s[20]||(s[20]=n(" 中嘗試它。",-1))]),s[44]||(s[44]=i("p",null,"你是否在使用其它的屏幕鏡像工具？如果有的話，請在評論中告訴我們吧。",-1)),s[45]||(s[45]=i("hr",null,null,-1)),i("p",null,[s[22]||(s[22]=n("via: ",-1)),t(e,{href:"https://opensource.com/article/21/3/android-raspberry-pi"},{default:a(()=>[...s[21]||(s[21]=[n("https://opensource.com/article/21/3/android-raspberry-pi",-1)])]),_:1})]),i("p",null,[s[27]||(s[27]=n("作者：",-1)),t(e,{href:"https://opensource.com/users/sudeshna-sur"},{default:a(()=>[...s[23]||(s[23]=[n("Sudeshna Sur",-1)])]),_:1}),s[28]||(s[28]=n(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[24]||(s[24]=[n("lujun9972",-1)])]),_:1}),s[29]||(s[29]=n(" 譯者：",-1)),t(e,{href:"https://github.com/ShuyRoy"},{default:a(()=>[...s[25]||(s[25]=[n("ShuyRoy",-1)])]),_:1}),s[30]||(s[30]=n(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[26]||(s[26]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[33]||(s[33]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[31]||(s[31]=[n("LCTT",-1)])]),_:1}),s[34]||(s[34]=n(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[32]||(s[32]=[n("Linux中國",-1)])]),_:1}),s[35]||(s[35]=n(" 榮譽推出",-1))])])}const S=l(u,[["render",b]]);export{T as __pageData,S as default};
